170	
171	/// Wrap a ready executor in the scheduler and hand the whole thing to the
172	/// contract: one scheduler, one driver thread, required metadata filled in.
173	pub(crate) fn start_with_executor<E>(
174	    executor: E,
175	    seed: u64,
176	    max_prefill_tokens: usize,
177	    lora_control: bool,
178	) -> Engine
179	where
180	    E: ModelExecutor + 'static,
181	{
182	    assert!(
183	        max_prefill_tokens > 0,
184	        "max_prefill_tokens must be positive: a zero budget can never schedule a prefill chunk"
185	    );
186	    let servable = servable_len(
187	        executor.max_context_tokens(),
188	        executor.max_request_blocks(),
189	        executor.block_size(),
190	    );
191	    // Executor just built: the only committed block is the leaked CUDA-graph
192	    // padding slot, so available_blocks() is total − 1. Conservative by one
193	    // block, which is the right side to err on for a capacity ceiling.
194	    let kv_total = executor.available_blocks() as u64;
195	    let kv_capacity = KvCapacity {
196	        total_blocks: kv_total as usize,
197	        block_size: executor.block_size(),
198	    };
199	    // The LoRA channel is qwen3's private wiring, minted before the thread
200	    // swallows the scheduler; the contract only carries the client.
201	    let (lora, lora_rx) = if lora_control {
202	        let (client, rx) = LoraClient::channel();
203	        (Some(client), Some(rx))
204	    } else {
205	        (None, None)
206	    };
207	    let scheduler = Qwen3Scheduler::new(executor, seed, max_prefill_tokens, kv_total, lora_rx);
208	    Engine {
209	        schedulers: vec![spawn_scheduler("qwen3-scheduler", scheduler)],
210	        info: EngineInfo {
211	            kv_capacity: Some(kv_capacity),
212	            servable_len: Some(servable),
213	        },
214	        lora,
215	    }
216	}
217	
218	// ── The Scheduler implementation ────────────────────────────────────────
219	
220	pub(crate) struct Qwen3Scheduler<E: ModelExecutor> {
221	    executor: E,
222	    rng: StdRng,
223	    max_prefill_tokens: usize,
224	    kv_total: u64,
225	    /// Host-side phase tracer (queue/prefill/decode spans). No-op when
226	    /// tracing is off — requests then carry no trace parent.
227	    tracker: PhaseTracker,
228	    /// Requests that could not be admitted yet (KV budget pressure).
229	    deferred: Vec<PendingRequest>,
230	    /// Requests parked while their async CPU-tier KV prefetch loads.
231	    loading: Vec<PendingRequest>,
232	    /// Admitted requests whose prompts are not fully prefilled yet (chunked
233	    /// prefill). FIFO by request id; each step takes chunks off the front.
234	    prefilling: Vec<PendingRequest>,
235	    /// An in-flight request being decoded.
236	    active: Vec<ActiveRequestState>,
237	    /// Decode-overlap async prefill: pending requests whose prefill is
238	    /// in-flight on the prefill overlap stream.
239	    inflight_prefill_pending: Option<Vec<PendingRequest>>,
240	    /// The engine's private LoRA channel, minted before spawn; `None` when
241	    /// this engine serves no adapter control. Drained at the top of every
242	    /// step into `pending_control`.
243	    lora_rx: Option<LoraControlReceiver>,
244	    /// LoRA commands wait here until the scheduler drains idle; generation
245	    /// submitted behind a pending command waits in `post_control_deferred` so
246	    /// it cannot run against an adapter set the command was about to change.
247	    pending_control: VecDeque<LoraControl>,
248	    post_control_deferred: Vec<PendingRequest>,
249	    /// Cumulative prefix-cache queries, in tokens: every admitted request adds
250	    /// its prompt length once, on its first prefill chunk. Monotonic; reported
251	    /// verbatim in `SchedulerMetrics`.
252	    prefix_cache_queries: u64,
253	    /// Cumulative prefix-cache hits, in tokens: of the queried tokens, those
254	    /// already cached locally. Same unit as `prefix_cache_queries`, so
255	    /// `hit_rate = hits/queries` stays in [0, 1]. Monotonic; the bridge exports
256	    /// per-send deltas of this total so Prometheus does not re-add the running
257	    /// total on every token batch.
258	    prefix_cache_hits: u64,
259	}
260	
261	impl<E: ModelExecutor> Qwen3Scheduler<E> {
262	    pub(crate) fn new(
263	        executor: E,
264	        seed: u64,
265	        max_prefill_tokens: usize,
266	        kv_total: u64,
267	        lora_rx: Option<LoraControlReceiver>,
268	    ) -> Self {
269	        Self {
270	            executor,
271	            rng: StdRng::seed_from_u64(seed),
272	            max_prefill_tokens,
273	            kv_total,
274	            tracker: PhaseTracker::default(),
275	            deferred: Vec::new(),
276	            loading: Vec::new(),
277	            prefilling: Vec::new(),
278	            active: Vec::new(),
