272	            max_prefill_tokens,
273	            kv_total,
274	            tracker: PhaseTracker::default(),
275	            deferred: Vec::new(),
276	            loading: Vec::new(),
277	            prefilling: Vec::new(),
278	            active: Vec::new(),
279	            inflight_prefill_pending: None,
280	            lora_rx,
281	            pending_control: VecDeque::new(),
282	            post_control_deferred: Vec::new(),
283	            prefix_cache_queries: 0,
284	            prefix_cache_hits: 0,
