288	    fn inflight_prefills(&self) -> &[PendingRequest] {
289	        self.inflight_prefill_pending.as_deref().unwrap_or_default()
290	    }
291	
292	    fn idle(&self) -> bool {
293	        self.active.is_empty()
294	            && self.deferred.is_empty()
295	            && self.prefilling.is_empty()
296	            && self.inflight_prefill_pending.is_none()
297	    }
298	
299	    /// Admit the request on the ledger. `false` (and full cleanup) when the
300	    /// frontend aborted it while it waited.
301	    fn admit_or_retire(&mut self, req: &PendingRequest, ledger: &mut RequestLedger) -> bool {
302	        if ledger.is_aborted(req.request_id) {
303	            ledger.retire(req.request_id);
304	            release_rejected(&mut self.executor, &mut self.tracker, req);
305	            return false;
306	        }
307	        ledger.admit(req.request_id);
308	        true
309	    }
310	
311	    fn reject_pending(
312	        &mut self,
313	        req: &PendingRequest,
314	        reason: RejectReason,
315	        ledger: &mut RequestLedger,
316	    ) {
317	        ledger.reject(req.request_id, reason);
318	        release_rejected(&mut self.executor, &mut self.tracker, req);
319	    }
320	
321	    /// Retire one request whose frontend aborted it: silent on the wire,
322	    /// full cleanup on the engine side.
323	    fn retire_aborted(&mut self, request_id: RequestId, ledger: &mut RequestLedger) {
324	        ledger.retire(request_id);
325	        self.tracker.finish(request_id);
326	        let _ = self.executor.drop_request(request_id);
327	    }
328	
329	    /// Retire every aborted request that has no prefill in flight: queued ones
330	    /// before they take admission room, and admitted ones waiting for their
331	    /// next prefill chunk, including those part way through their prompt,
332	    /// before that chunk runs. `loading` waits for its prefetch to settle,
333	    /// `active` retires on its next decode, and an in-flight async prefill
334	    /// keeps its KV until its result lands.
335	    fn retire_aborted_waiting(&mut self, ledger: &mut RequestLedger) {
336	        for queue in [&mut self.deferred, &mut self.post_control_deferred] {
337	            let (aborted, kept): (Vec<_>, Vec<_>) = std::mem::take(queue)
338	                .into_iter()
339	                .partition(|req| ledger.is_aborted(req.request_id));
340	            *queue = kept;
341	            for req in &aborted {
342	                ledger.retire(req.request_id);
343	                release_rejected(&mut self.executor, &mut self.tracker, req);
344	            }
345	        }
346	        let (aborted, kept): (Vec<_>, Vec<_>) = std::mem::take(&mut self.prefilling)
347	            .into_iter()
348	            .partition(|req| ledger.is_aborted(req.request_id));
349	        self.prefilling = kept;
350	        for req in aborted {
351	            self.retire_aborted(req.request_id, ledger);
352	        }
353	    }
354	
355	    /// Fail the batch a step execution error touched, then clear the running
356	    /// set — the same requests the plan was about to advance.
357	    fn fail_touched_requests(
358	        &mut self,
359	        targets: Vec<RequestId>,
360	        message: &str,
361	        ledger: &mut RequestLedger,
362	    ) {
363	        for request_id in targets {
364	            if ledger.is_active(request_id) {
365	                ledger.fail(request_id, message);
366	            }
367	            // Close the request's open phase span; an execution error is a
368	            // termination path like any other finish.
369	            self.tracker.finish(request_id);
370	            if let Err(error) = self.executor.drop_request(request_id) {
371	                warn!(
372	                    "failed to drop request state after execution error for {request_id:?}: {error}"
373	                );
374	            }
375	        }
376	        self.active.clear();
377	    }
