379	    /// Absorb a step execution error by failing the batch it touched. A lost
380	    /// rank worker leaves nothing to serve with, so that error is returned and
381	    /// the driver winds the engine down.
382	    fn absorb_step_failure(
383	        &mut self,
384	        targets: Vec<RequestId>,
385	        error: anyhow::Error,
386	        ledger: &mut RequestLedger,
387	    ) -> Result<()> {
388	        if WorkerLost::caused(&error) {
389	            return Err(error);
