619	    fn submit(&mut self, request: QueuedRequest) {
620	        // Already-aborted requests ride the normal path: admission re-checks
621	        // the abort flag and retires them (`admit_or_retire`).
622	        let QueuedRequest { id, request } = request;
623	        self.tracker.enter_queue(id, request.trace_parent);
624	        let pending = PendingRequest::from_request(id, request);
625	        if self.pending_control.is_empty() {
626	            self.deferred.push(pending);
627	        } else {
628	            self.post_control_deferred.push(pending);
629	        }
630	    }
631	
632	    fn step(&mut self, ledger: &mut RequestLedger) -> Result<()> {
633	        // 0. Pull queued LoRA commands off the engine's private channel; they
634	        // apply only once the scheduler drains idle (`drain_idle_control`).
635	        if let Some(lora_rx) = &self.lora_rx {
636	            while let Ok(control) = lora_rx.try_recv() {
637	                self.pending_control.push_back(control);
638	            }
639	        }
640	
641	        // 1. Poll in-flight async prefill (decode-overlap mode).
642	        if self.inflight_prefill_pending.is_some()
643	            && let Some(prefill_result) = self.executor.poll_async_prefill()
644	        {
645	            let pending = self
646	                .inflight_prefill_pending
647	                .take()
648	                .expect("checked in-flight prefill above");
649	            info!(
650	                "decode-overlap: async prefill completed ({} reqs)",
651	                pending.len()
652	            );
653	            let artifacts = ExecutionArtifacts::Prefill {
654	                pending,
655	                result: prefill_result,
656	            };
657	            let effects = resolve_step(&self.executor, &self.active, artifacts);
658	            self.apply_effects(effects, ledger);
659	        }
660	        self.retire_aborted_waiting(ledger);
661	
662	        // 2. Reclaim settled prefetches, then offer fresh requests to
663	        // prefetch. Control commands gate generation, so only offer once no
664	        // control is pending (a prefetch must not race ahead of an adapter
665	        // load it depends on).
666	        let reserve_floor = admitted_future_blocks(
667	            &self.executor,
668	            &self.active,
669	            &self.prefilling,
670	            self.inflight_prefills(),
671	        );
672	        reclaim_ready_prefetch(
673	            &mut self.executor,
674	            &mut self.deferred,
675	            &mut self.loading,
676	            reserve_floor,
677	        );
678	        if self.pending_control.is_empty() {
679	            offer_prefetch(
680	                &mut self.executor,
681	                &mut self.deferred,
682	                &mut self.loading,
683	                reserve_floor,
684	            );
685	        }
686	
687	        // 3. Once idle, apply pending control commands before admitting newer
688	        // generation requests that arrived behind them.
689	        if self.idle() {
690	            self.drain_idle_control();
691	            if self.pending_control.is_empty() && !self.post_control_deferred.is_empty() {
692	                self.deferred.append(&mut self.post_control_deferred);
693	            }
694	        }
695	
696	        // 4. Still nothing runnable → wait on an in-flight prefetch DMA (its
697	        // request prefills next), else hand control back to the polling
698	        // driver.
699	        if self.idle() {
700	            if !self.loading.is_empty() {
701	                let reserve_floor = admitted_future_blocks(
702	                    &self.executor,
703	                    &self.active,
704	                    &self.prefilling,
705	                    self.inflight_prefills(),
706	                );
707	                block_on_loading(
708	                    &mut self.executor,
709	                    &mut self.deferred,
710	                    &mut self.loading,
711	                    reserve_floor,
712	                );
713	            }
714	            return Ok(());
715	        }
716	
717	        // 5. Validate + admit; every verdict closes the request's queued
718	        //    ledger account.
719	        let lora_validation =
720	            reject_unknown_lora_requests(std::mem::take(&mut self.deferred), &self.executor);
721	        for rejected in &lora_validation.rejected {
722	            let reason = RejectReason::UnknownLoraAdapter {
723	                name: rejected
724	                    .lora_adapter
725	                    .clone()
726	                    .expect("only requests naming an adapter can fail LoRA validation"),
727	            };
728	            self.reject_pending(rejected, reason, ledger);
729	        }
730	        let admission = admit_deferred_requests(
731	            lora_validation.accepted,
732	            &self.active,
733	            &self.prefilling,
734	            self.inflight_prefills(),
735	            self.executor.block_size(),
736	            self.executor.available_blocks(),
737	            self.executor.max_request_blocks(),
738	            self.executor.max_context_tokens(),
739	            self.executor.max_decode_batch_size(),
740	            self.max_prefill_tokens,
741	            |id| self.executor.prefetched_blocks(id),
