743	        for (rejected, reason) in &admission.rejected {
744	            self.reject_pending(rejected, contract_reject_reason(rejected, *reason), ledger);
745	        }
746	        self.deferred = admission.deferred;
747	        for req in admission.pending {
748	            if self.admit_or_retire(&req, ledger) {
