750	            }
751	        }
752	
753	        // 6. Chunk selection. While an async prefill is in flight, only
754	        // decode runs.
755	        let pending = if self.inflight_prefill_pending.is_some() {
756	            Vec::new()
757	        } else {
758	            take_prefill_chunks(
759	                &mut self.prefilling,
760	                self.max_prefill_tokens,
761	                matches!(
762	                    numeric_policy(),
763	                    NumericPolicy::Pin | NumericPolicy::PerToken
764	                ),
765	            )
766	        };
767	        // These requests' prompt work is about to hit the GPU this step:
768	        // close their queue span, open prefill. Idempotent, so chunked
769	        // prefill across steps opens the prefill span once (on the first
770	        // chunk).
771	        for req in &pending {
772	            self.tracker.enter_prefill(req.request_id);
773	        }
774	
775	        let Some(plan) = runtime_plan(&self.executor, &self.active, pending) else {
776	            return Ok(());
777	        };
778	
779	        // 7. Decode-overlap path: when a Unified plan appears and overlap
780	        // streams are active (and no async prefill is already in-flight),
781	        // execute_unified internally uses SplitConcurrent which only syncs
782	        // decode and defers the prefill sync. The prefill result is polled at
783	        // the top of a later step.
784	        if self.executor.has_decode_overlap()
785	            && self.inflight_prefill_pending.is_none()
786	            && let ExecutionPlan::Unified { pending } = plan
787	        {
788	            let prefill_tokens: usize = pending.iter().map(|r| r.step_chunk).sum();
789	            info!(
790	                "decode-overlap: unified step with async prefill ({} reqs, ~{} tokens)",
791	                pending.len(),
792	                prefill_tokens
793	            );
794	            let pending_for_poll = pending.clone();
795	            let unified_plan = ExecutionPlan::Unified { pending };
796	            let targets = failure_target_ids(&self.active, &unified_plan);
797	            let artifacts = match execute_plan(
798	                &mut self.executor,
799	                &mut self.active,
800	                unified_plan,
801	                &mut self.rng,
802	            ) {
803	                Ok(v) => v,
804	                Err(e) => return self.absorb_step_failure(targets, e, ledger),
805	            };
806	            // Only decode effects come out of the unified result (its prefill
807	            // request list is empty until the poll resolves).
808	            let effects = resolve_step(&self.executor, &self.active, artifacts);
809	            self.apply_effects(effects, ledger);
810	            self.inflight_prefill_pending = Some(pending_for_poll);
811	            return Ok(());
812	        }
813	
814	        // 8. Execute, resolve, apply. A step failure kills the touched batch
815	        // but not the engine, unless a rank worker is gone.
816	        let targets = failure_target_ids(&self.active, &plan);
817	        let artifacts =
818	            match execute_plan(&mut self.executor, &mut self.active, plan, &mut self.rng) {
819	                Ok(v) => v,
820	                Err(e) => return self.absorb_step_failure(targets, e, ledger),
821	            };
822	        let effects = resolve_step(&self.executor, &self.active, artifacts);
823	        self.apply_effects(effects, ledger);
824	        Ok(())
825	    }
