829	    /// not-yet-running queue (KV-deferred, prefetch-loading, post-control)
830	    /// into one number.
831	    fn metrics(&self) -> SchedulerMetrics {
832	        // The external family lives on the executor: a connector lookup is
833	        // settled there whether or not its request ever reaches a prefill.
834	        let connector = self.executor.connector_lookup_counters();
835	        SchedulerMetrics {
836	            kv_used_blocks: self
837	                .kv_total
838	                .saturating_sub(self.executor.available_blocks() as u64),
839	            kv_total_blocks: self.kv_total,
840	            num_running_reqs: (self.active.len()
841	                + self.prefilling.len()
842	                + self.inflight_prefill_pending.as_ref().map_or(0, Vec::len))
843	                as u64,
844	            num_waiting_reqs: (self.deferred.len()
845	                + self.loading.len()
846	                + self.post_control_deferred.len()) as u64,
847	            spec_decode: self.executor.spec_decode_counters(),
848	            prefix_cache: Some(pegainfer_frontend::engine::PrefixCacheCounters {
849	                queries: self.prefix_cache_queries,
850	                // hits = local hits + connector hits; the bridge derives the
851	                // local ones as `hits - external hits` for
852	                // `vllm:prefix_cache_hits`.
853	                hits: self.prefix_cache_hits + connector.hits,
854	                // The connector's lookups ride `host_queries`, the family's
855	                // source-agnostic query count. A connector query returns only
856	                // a block count: it can be answered from host memory, a P2P
857	                // peer or SSD, and nothing says which. So the hits are
858	                // `external_unspecified`, not `host`, which would mislabel the
859	                // peer and disk restores.
860	                host_queries: connector.queries,
861	                external_unspecified_hits: connector.hits,
862	                ..pegainfer_frontend::engine::PrefixCacheCounters::default()
863	            }),
864	        }
865	    }
866	}
867	
868	/// Widen a mechanics-side admission verdict into the contract's typed reason:
869	/// the mechanics carry only what the decision needed, the request at hand
870	/// supplies the rest.
871	fn contract_reject_reason(req: &PendingRequest, reason: AdmissionReject) -> RejectReason {
872	    match reason {
873	        AdmissionReject::ContextLength { limit } => RejectReason::ContextLength {
874	            prompt_tokens: req.prompt_tokens.len(),
875	            max_tokens: req.max_tokens,
876	            limit,
877	        },
878	        AdmissionReject::EchoPrefillTokens { limit } => RejectReason::EchoPrefillTokens {
879	            prompt_tokens: req.prompt_tokens.len(),
880	            limit,
881	        },
882	        AdmissionReject::KvBudget => RejectReason::KvBudget {
883	            prompt_tokens: req.prompt_tokens.len(),
884	            worst_case_tokens: max_request_tokens(req),
885	        },
886	    }
887	}
888	
889	fn handle_control_request(executor: &mut impl ModelExecutor, control: LoraControl) {
890	    match control {
891	        LoraControl::Load { request, reply } => {
892	            info!(
893	                "LoRA adapter load applied while scheduler is idle: name={}, path={}",
894	                request.lora_name,
895	                request.lora_path.display()
896	            );
897	            let _ = reply.send(
898	                executor
899	                    .load_lora_adapter(&request)
900	                    .map_err(|error| error.to_string()),
901	            );
902	        }
903	        LoraControl::Unload { request, reply } => {
904	            info!(
905	                "LoRA adapter unload applied while scheduler is idle: name={}",
906	                request.lora_name
907	            );
908	            let _ = reply.send(
909	                executor
910	                    .unload_lora_adapter(&request)
911	                    .map_err(|error| error.to_string()),
912	            );
913	        }
914	        LoraControl::List { reply } => {
915	            let _ = reply.send(executor.list_lora_adapters());
916	        }
917	    }
918	}
