1695	    /// Configure two-stream prefill/decode overlap (see [`crate::DecodeOverlap`]).
1696	    /// A no-op for [`crate::DecodeOverlap::Off`]; otherwise sets up the streams,
1697	    /// returning an error if the GPU/driver cannot honor the requested mode.
1698	    pub(crate) fn enable_decode_overlap(&mut self, overlap: crate::DecodeOverlap) -> Result<()> {
1699	        // Pre-capture backstop: a runtime caller could set Pin then enable overlap here, bypassing the
1700	        // engine-entry guard. launch_gemm_pin also bails on the resulting stream override, but only mid
1701	        // graph-capture/replay (a hot-path failure) — rejecting here moves it to a safe point.
1702	        anyhow::ensure!(
1703	            pegainfer_kernels::ops::numeric_policy() != pegainfer_kernels::ops::NumericPolicy::Pin
1704	                || matches!(overlap, crate::DecodeOverlap::Off),
1705	            "--batch-invariant (NumericPolicy::Pin) is not compatible with decode-overlap: the stream override would force the pinned GEMM to bail at runtime"
1706	        );
1707	        // PerToken profiles only the full-SM graph cache. Overlap captures into
1708	        // the independent split-stream cache, which would otherwise be unbudgeted.
1709	        ensure_pertoken_overlap_disabled(pegainfer_kernels::ops::numeric_policy(), overlap)?;
1710	
1711	        // Overlap's split-concurrent decode stream uses the group-limited decode
1712	        // kernel this GQA group can't instantiate; reject at load, not mid-serving.
1713	        anyhow::ensure!(
1714	            self.metadata.config.decode_group_is_compiled()
1715	                || matches!(overlap, crate::DecodeOverlap::Off),
1716	            "decode-overlap is unsupported for GQA group size {}/{}: no compiled decode kernel",
1717	            self.metadata.config.num_attention_heads,
1718	            self.metadata.config.num_key_value_heads,
1719	        );
1720	        // TP decode graphs are pre-captured on the compute stream only; a split
1721	        // decode stream would route capture into the graphs_split cache with no
1722	        // cross-rank alignment (and the streams below are built on device 0).
1723	        anyhow::ensure!(
1724	            self.workers.is_empty() || matches!(overlap, crate::DecodeOverlap::Off),
1725	            "decode-overlap is unsupported under tensor parallelism"
1726	        );
1727	        let device_ordinal = self.device_ordinal;
1728	        self.overlap = crate::green_ctx::OverlapStreams::create(device_ordinal, overlap)?;
1729	        Ok(())
1730	    }
1731	
1732	    /// vLLM-style `--no-prefix-cache`. Behaviour depends on whether offload is
1733	    /// active:
1734	    ///   * **No offload** — classic: disable prefix matching outright, so every
1735	    ///     prefill recomputes the full prompt.
1736	    ///   * **With offload** — pure-L2 mode: keep matching on (the host-tier
1737	    ///     restore registers blocks and relies on `match_and_add_prefix` to pick
1738	    ///     them up) but stop retaining completed blocks in HBM, so no request
1739	    ///     ever serves its prefix from a cross-request L1 hit. Every reuse then
1740	    ///     comes from the host tier, which is the point of the L2 benchmark.
1741	    ///
1742	    /// A resident HBM block and its host-tier copy share one content hash, so
1743	    /// the cache cannot be told to prefer L2 for a block still in HBM — the only
1744	    /// way to force the bytes from L2 is to not keep the HBM copy around.
1745	    pub(crate) fn set_no_prefix_cache(&mut self, on: bool) {
1746	        if self.offload.is_some() {
1747	            let retained_before = self.retains_completed_kv_blocks();
1748	            self.l1_retention_disabled = on;
1749	            self.finish_retention_transition(retained_before);
1750	        } else {
1751	            self.set_prefix_cache_enabled(!on);
1752	        }
1753	    }
1754	
1755	    /// Enable speculative decoding by loading a DFlash draft model into the
1756	    /// primary lane.
1757	    ///
1758	    /// Requires the single-GPU topology (tensor parallel shards KV per rank) and
1759	    /// is incompatible with KV offload. Disables the prefix cache: speculative
1760	    /// capture needs clean, uncached target hidden states for every prompt
1761	    /// token, and a prefix-cache hit skips the forward that would produce them.
